PRAGMA foreign_keys=ON;
CREATE TABLE MaterialTypes(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE, Loss REAL NOT NULL CHECK(Loss>=0 AND Loss<1));
CREATE TABLE ProductTypes(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE, Coefficient REAL NOT NULL CHECK(Coefficient>0));
CREATE TABLE Units(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE Materials(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE, TypeId INTEGER NOT NULL REFERENCES MaterialTypes(Id), Price REAL NOT NULL CHECK(Price>=0 AND round(Price,2)=Price), Stock REAL NOT NULL CHECK(Stock>=0), Minimum REAL NOT NULL CHECK(Minimum>=0), Pack REAL NOT NULL CHECK(Pack>0), UnitId INTEGER NOT NULL REFERENCES Units(Id));
CREATE TABLE Products(Id INTEGER PRIMARY KEY, Article TEXT NOT NULL UNIQUE, TypeId INTEGER NOT NULL REFERENCES ProductTypes(Id), Name TEXT NOT NULL UNIQUE, Price REAL NOT NULL CHECK(Price>=0));
CREATE TABLE Recipes(MaterialId INTEGER NOT NULL REFERENCES Materials(Id), ProductId INTEGER NOT NULL REFERENCES Products(Id), Quantity REAL NOT NULL CHECK(Quantity>0), PRIMARY KEY(MaterialId,ProductId));
